package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import java.time.Instant;
import org.junit.Test;

public class TrawlAttemptCounterTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T00:00:00Z");

	private static Instant seconds(double s)
	{
		return T0.plusMillis((long) (s * 1000));
	}

	@Test
	public void firstUpdateOnlySetsBaseline()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		assertEquals(0, counter.onXp(50_000));
		assertEquals(15, counter.onXp(50_015));
	}

	@Test
	public void sameXpIsNoDrop()
	{
		// StatChanged also fires for boosted level changes and on re-login with unchanged XP
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.onXp(50_000);
		assertEquals(0, counter.onXp(50_000));
	}

	@Test
	public void clearedBaselineSwallowsLoginResend()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.onXp(50_000);
		counter.clearBaseline();
		// Log into an account with much more Sailing XP
		assertEquals(0, counter.onXp(900_000));
		assertEquals(15, counter.onXp(900_015));
	}

	@Test
	public void explicitBaselineMakesNextUpdateADrop()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.setBaseline(50_000);
		assertEquals(15, counter.onXp(50_015));
	}

	@Test
	public void resetKeepsBaseline()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.onXp(50_000);
		counter.setAttempts(1_234);
		counter.recordAttempt(T0);
		counter.reset();
		assertEquals(0, counter.getAttempts());
		assertEquals(15, counter.onXp(50_015));
	}

	@Test
	public void attemptsAddToSavedTotal()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.setAttempts(100_000);
		counter.recordAttempt(T0);
		counter.recordAttempt(seconds(1.8));
		assertEquals(100_002, counter.getAttempts());
	}

	@Test
	public void attemptsPerHour()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.recordAttempt(T0);
		assertEquals(-1, counter.attemptsPerHour(T0));

		// One roll every 3 ticks (1.8s) is 2,000/hr
		counter.recordAttempt(seconds(1.8));
		counter.recordAttempt(seconds(3.6));
		assertEquals(2_000, counter.attemptsPerHour(seconds(3.6)));

		// Decays while idle
		assertEquals(1_000, counter.attemptsPerHour(seconds(7.2)));
	}

	@Test
	public void longGapStartsNewTrip()
	{
		TrawlAttemptCounter counter = new TrawlAttemptCounter();
		counter.recordAttempt(T0);
		counter.recordAttempt(seconds(1.8));

		Instant later = seconds(3_600);
		counter.recordAttempt(later);
		assertEquals(-1, counter.attemptsPerHour(later));
		counter.recordAttempt(later.plusMillis(1_800));
		assertEquals(2_000, counter.attemptsPerHour(later.plusMillis(1_800)));
		assertEquals(4, counter.getAttempts());
	}
}

package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class RareFishCounterTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T00:00:00Z");

	@Test
	public void regularShoalCatchCountsForItsOneFish()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.recordCatch(Shoal.MARLIN, T0);
		assertEquals(2, counter.getTotalCatches(RareFish.SWIFT_MARLIN));
		assertEquals(0, counter.getTotalCatches(RareFish.PURPLEFIN));
		assertEquals(Collections.singletonList(RareFish.SWIFT_MARLIN), counter.getCurrentFish());
	}

	@Test
	public void mixedShoalCatchCountsForEveryFishItRollsFor()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.GLISTENING, T0);
		for (RareFish fish : Arrays.asList(RareFish.ORANGEFIN, RareFish.HUGE_HALIBUT, RareFish.PURPLEFIN, RareFish.SWIFT_MARLIN))
		{
			assertEquals(1, counter.getTotalCatches(fish));
		}
		assertEquals(0, counter.getTotalCatches(RareFish.GOLDEN_HADDOCK));
	}

	@Test
	public void homeFishStaysOnTopAtAMixedShoalAndExtrasGoAwayAfter()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.recordCatch(Shoal.VIBRANT, T0);
		assertEquals(Arrays.asList(RareFish.SWIFT_MARLIN, RareFish.PURPLEFIN), counter.getCurrentFish());

		counter.recordCatch(Shoal.GLISTENING, T0);
		assertEquals(Arrays.asList(RareFish.SWIFT_MARLIN, RareFish.ORANGEFIN, RareFish.HUGE_HALIBUT, RareFish.PURPLEFIN),
			counter.getCurrentFish());

		counter.recordCatch(Shoal.MARLIN, T0);
		assertEquals(Collections.singletonList(RareFish.SWIFT_MARLIN), counter.getCurrentFish());
	}

	@Test
	public void mixedShoalWithNoRegularShoalYetKeepsTableOrder()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.VIBRANT, T0);
		assertEquals(Arrays.asList(RareFish.PURPLEFIN, RareFish.SWIFT_MARLIN), counter.getCurrentFish());
	}

	@Test
	public void oddsUseEachShoalsRate()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.MARLIN, 3_000);
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.GLISTENING, 20_000);
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.VIBRANT, 3_000);
		assertEquals(26_000, counter.getTotalCatches(RareFish.SWIFT_MARLIN));
		// 3,000/6,000 + 20,000/40,000 + 3,000/6,000
		assertEquals(1.5, counter.getOdds(RareFish.SWIFT_MARLIN).timesDropRate(), 1e-12);
	}

	@Test
	public void resetClearsOneFishAtEveryShoal()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.VIBRANT, T0);
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.reset(RareFish.SWIFT_MARLIN);
		assertEquals(0, counter.getTotalCatches(RareFish.SWIFT_MARLIN));
		assertEquals(1, counter.getTotalCatches(RareFish.PURPLEFIN));
	}

	@Test
	public void tracksLastCatch()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.recordCatch(Shoal.HALIBUT, T0.plusSeconds(60));
		assertEquals(Shoal.HALIBUT, counter.getCurrent());
		assertEquals(T0.plusSeconds(60), counter.getLastCatch());
	}

	@Test
	public void setTotalPutsCarriedOverCatchesAtTheRegularShoal()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.setTotalCatches(RareFish.SWIFT_MARLIN, 4_500);
		assertEquals(4_500, counter.getCatches(RareFish.SWIFT_MARLIN, Shoal.MARLIN));
		assertEquals(0.75, counter.getOdds(RareFish.SWIFT_MARLIN).timesDropRate(), 1e-12);
	}

	@Test
	public void setTotalKeepsMixedShoalCatchesThatFit()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.MARLIN, 1_000);
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.GLISTENING, 400);
		counter.setTotalCatches(RareFish.SWIFT_MARLIN, 5_000);
		assertEquals(4_600, counter.getCatches(RareFish.SWIFT_MARLIN, Shoal.MARLIN));
		assertEquals(400, counter.getCatches(RareFish.SWIFT_MARLIN, Shoal.GLISTENING));
		assertEquals(5_000, counter.getTotalCatches(RareFish.SWIFT_MARLIN));
	}

	@Test
	public void setTotalBelowMixedShoalCatchesPutsAllAtTheRegularShoal()
	{
		RareFishCounter counter = new RareFishCounter();
		counter.setCatches(RareFish.SWIFT_MARLIN, Shoal.VIBRANT, 800);
		counter.setTotalCatches(RareFish.SWIFT_MARLIN, 300);
		assertEquals(300, counter.getCatches(RareFish.SWIFT_MARLIN, Shoal.MARLIN));
		assertEquals(0, counter.getCatches(RareFish.SWIFT_MARLIN, Shoal.VIBRANT));
		assertEquals(300, counter.getTotalCatches(RareFish.SWIFT_MARLIN));
	}
}

package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CatchMessageTest
{
	@Test
	public void playerCatches()
	{
		CatchMessage single = CatchMessage.parse("You catch a marlin!");
		assertTrue(single.isByPlayer());
		assertEquals("a marlin", single.getCaught());

		CatchMessage several = CatchMessage.parse("You catch 3 marlin!");
		assertTrue(several.isByPlayer());
		assertEquals("3 marlin", several.getCaught());
	}

	@Test
	public void crewmateCatches()
	{
		CatchMessage crew = CatchMessage.parse("Jolly Jim catches a swift marlin!");
		assertFalse(crew.isByPlayer());
		assertEquals("a swift marlin", crew.getCaught());
	}

	@Test
	public void ignoresOtherMessages()
	{
		// Full nets, the crew XP message, the paint drop, and this plugin's own chat lines
		assertNull(CatchMessage.parse("Your net has no more space for any swift marlin."));
		assertNull(CatchMessage.parse("Your nets are too full to hold any more marlin."));
		assertNull(CatchMessage.parse("You gain some experience by watching your crew work."));
		assertNull(CatchMessage.parse("You've received some paint!"));
		assertNull(CatchMessage.parse("Catch at vibrant shoal counted toward purplefin, swift marlin, angler's paint"));
		assertNull(CatchMessage.parse("Sailing XP drop: 15 (Soup attempt)"));
	}
}

package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.LinkedHashSet;
import org.junit.Test;

public class CountedXpDropsTest
{
	@Test
	public void defaultsCountYoursAndNotTheCrewsWithACottonNet()
	{
		CountedXpDrops drops = CountedXpDrops.parse(CountedXpDrops.DEFAULT);
		// You at the right depth, you at the wrong depth, and either plus a crewmate
		assertTrue(drops.counts(15));
		assertTrue(drops.counts(7));
		assertTrue(drops.counts(8));
		assertTrue(drops.counts(25));
		assertTrue(drops.counts(26));
		assertTrue(drops.counts(18));
		// A crewmate alone, and two crewmates
		assertFalse(drops.counts(10));
		assertFalse(drops.counts(11));
		assertFalse(drops.counts(21));
		// Other Sailing activities
		assertFalse(drops.counts(31));
		assertFalse(drops.counts(1_200));
	}

	@Test
	public void horizonsLureShiftsEverySizeButNotTheCrewsOwn()
	{
		CountedXpDrops drops = CountedXpDrops.parse(CountedXpDrops.WITH_HORIZONS_LURE);
		// 15.3 arrives as 15 or 16, the wrong depth's 7.6 as 7 or 8
		assertTrue(drops.counts(15));
		assertTrue(drops.counts(16));
		assertTrue(drops.counts(7));
		assertTrue(drops.counts(8));
		// You and a crewmate: 15.3 + 10.7 is a whole 26, and 18.3 at the wrong depth
		assertTrue(drops.counts(26));
		assertTrue(drops.counts(18));
		assertTrue(drops.counts(19));
		assertFalse(drops.counts(25));
		assertFalse(drops.counts(27));
		// A crewmate's 10.7 alone, and two crewmates' 21.4 together
		assertFalse(drops.counts(10));
		assertFalse(drops.counts(11));
		assertFalse(drops.counts(21));
		assertFalse(drops.counts(22));
	}

	@Test
	public void readsAListInAnyReasonableShape()
	{
		assertEquals(new LinkedHashSet<>(Arrays.asList(7, 8, 15)), CountedXpDrops.parse(" 7,8 , 15 ").getSizes());
		assertEquals(new LinkedHashSet<>(Arrays.asList(7, 8, 15)), CountedXpDrops.parse("7 8 15").getSizes());
		assertEquals(new LinkedHashSet<>(Arrays.asList(15, 16)), CountedXpDrops.parse("15-16").getSizes());
		assertEquals(new LinkedHashSet<>(Arrays.asList(15)), CountedXpDrops.parse("15, 15").getSizes());
	}

	@Test
	public void emptyOrUnreadableGoesBackToTheDefaults()
	{
		CountedXpDrops fallback = CountedXpDrops.parse(CountedXpDrops.DEFAULT);
		assertEquals(fallback.getSizes(), CountedXpDrops.parse("").getSizes());
		assertEquals(fallback.getSizes(), CountedXpDrops.parse("   ").getSizes());
		assertEquals(fallback.getSizes(), CountedXpDrops.parse("none").getSizes());
		assertEquals(fallback.getSizes(), CountedXpDrops.parse(null).getSizes());
	}

	@Test
	public void ignoresNumbersTooLargeToBeAnXpDrop()
	{
		assertEquals(new LinkedHashSet<>(Arrays.asList(15)), CountedXpDrops.parse("15, 99999999999999").getSizes());
	}
}

package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class DropOddsTest
{
	@Test
	public void singleRate()
	{
		DropOdds odds = new DropOdds().add(180_000, 1.0 / 360_000);
		assertEquals(0.5, odds.timesDropRate(), 1e-12);
		// 1 - (1 - 1/360,000)^180,000
		assertEquals(0.39347, odds.chanceByNow(), 1e-5);
	}

	@Test
	public void noRolls()
	{
		DropOdds odds = new DropOdds();
		assertEquals(0.0, odds.timesDropRate(), 0);
		assertEquals(0.0, odds.chanceByNow(), 0);
	}

	@Test
	public void atTheDropRateItsAboutOneMinusOneOverE()
	{
		assertEquals(0.63212, new DropOdds().add(360_000, 1.0 / 360_000).chanceByNow(), 1e-5);
		assertEquals(0.63215, new DropOdds().add(6_000, 1.0 / 6_000).chanceByNow(), 1e-5);
		assertEquals(0.86469, new DropOdds().add(12_000, 1.0 / 6_000).chanceByNow(), 1e-5);
	}

	@Test
	public void mixedRatesCombine()
	{
		// 3,000 marlin shoal catches at 1/6,000 and 20,000 glistening catches at 1/40,000
		DropOdds odds = new DropOdds().add(3_000, 1.0 / 6_000).add(20_000, 1.0 / 40_000);
		assertEquals(1.0, odds.timesDropRate(), 1e-12);
		double expected = 1 - Math.pow(1 - 1.0 / 6_000, 3_000) * Math.pow(1 - 1.0 / 40_000, 20_000);
		assertEquals(expected, odds.chanceByNow(), 1e-12);
	}
}

package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.time.Instant;
import org.junit.Test;

public class PaintCounterTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T00:00:00Z");

	@Test
	public void rateDependsOnShoalType()
	{
		assertEquals(18_000, PaintCounter.oneIn(Shoal.MARLIN));
		assertEquals(16_200, PaintCounter.oneIn(Shoal.VIBRANT));
	}

	@Test
	public void countsRegularAndMixedCatchesSeparately()
	{
		PaintCounter counter = new PaintCounter();
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.recordCatch(Shoal.VIBRANT, T0.plusSeconds(5));
		assertEquals(2, counter.getRegularCatches());
		assertEquals(1, counter.getMixedCatches());
		assertEquals(3, counter.getTotalCatches());
		assertEquals(T0.plusSeconds(5), counter.getLastCatch());
	}

	@Test
	public void oddsUseEachRate()
	{
		PaintCounter counter = new PaintCounter();
		counter.setRegularCatches(9_000);
		counter.setMixedCatches(8_100);
		// 9,000/18,000 + 8,100/16,200
		assertEquals(1.0, counter.getOdds().timesDropRate(), 1e-12);
	}

	@Test
	public void reset()
	{
		PaintCounter counter = new PaintCounter();
		counter.recordCatch(Shoal.MARLIN, T0);
		counter.recordCatch(Shoal.GLISTENING, T0);
		counter.reset();
		assertEquals(0, counter.getTotalCatches());
		assertNull(counter.getLastCatch());
	}

	@Test
	public void setTotalKeepsMixedCatchesThatFit()
	{
		PaintCounter counter = new PaintCounter();
		counter.setMixedCatches(200);
		counter.setTotalCatches(1_000);
		assertEquals(800, counter.getRegularCatches());
		assertEquals(200, counter.getMixedCatches());

		counter.setTotalCatches(100);
		assertEquals(100, counter.getRegularCatches());
		assertEquals(0, counter.getMixedCatches());
	}
}

