package com.trawlingtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class ShoalTest
{
	@Test
	public void catchMessagesNameTheirRegularShoal()
	{
		assertEquals(Shoal.GIANT_KRILL, Shoal.regularFromCatch("4 giant krill"));
		assertEquals(Shoal.GIANT_KRILL, Shoal.regularFromCatch("a giant blue krill"));
		assertEquals(Shoal.HADDOCK, Shoal.regularFromCatch("2 haddock"));
		assertEquals(Shoal.YELLOWFIN, Shoal.regularFromCatch("a yellowfin"));
		assertEquals(Shoal.YELLOWFIN, Shoal.regularFromCatch("an orangefin"));
		assertEquals(Shoal.HALIBUT, Shoal.regularFromCatch("3 halibut"));
		assertEquals(Shoal.BLUEFIN, Shoal.regularFromCatch("a purplefin"));
		assertEquals(Shoal.MARLIN, Shoal.regularFromCatch("a swift marlin"));
		assertNull(Shoal.regularFromCatch("a shark"));
	}

	@Test
	public void objectIds()
	{
		assertEquals(Shoal.MARLIN, Shoal.fromObjectId(ObjectID.SAILING_SHOAL_CLICKBOX_MARLIN));
		assertEquals(Shoal.VIBRANT, Shoal.fromObjectId(ObjectID.SAILING_SHOAL_CLICKBOX_VIBRANT));
		assertNull(Shoal.fromObjectId(ObjectID.SAILING_COTTON_TRAWLING_NET));
	}

	@Test
	public void mixedShoalsYieldTheirRegularShoalsFish()
	{
		assertTrue(Shoal.VIBRANT.yields(Shoal.MARLIN));
		assertTrue(Shoal.VIBRANT.yields(Shoal.BLUEFIN));
		assertFalse(Shoal.VIBRANT.yields(Shoal.HALIBUT));
		assertTrue(Shoal.GLISTENING.yields(Shoal.MARLIN));
		assertTrue(Shoal.MARLIN.yields(Shoal.MARLIN));
		assertFalse(Shoal.MARLIN.yields(Shoal.BLUEFIN));
	}

	@Test
	public void mixedShoalRatesAddUpToTheirRareTable()
	{
		// The wiki gives each mixed shoal's overall rare table chance, then how it's split
		assertEquals(1.0 / 1_000, totalChance(Shoal.SHIMMERING), 1e-15);
		assertEquals(1.0 / 2_000, totalChance(Shoal.GLISTENING), 1e-15);
		assertEquals(1.0 / 3_000, totalChance(Shoal.VIBRANT), 1e-15);
	}

	@Test
	public void rateText()
	{
		assertEquals("1/6,000", Shoal.MARLIN.rollFor(RareFish.SWIFT_MARLIN).rateText());
		assertEquals("9/20,000", Shoal.SHIMMERING.rollFor(RareFish.GIANT_BLUE_KRILL).rateText());
		assertNull(Shoal.MARLIN.rollFor(RareFish.PURPLEFIN));
	}

	private static double totalChance(Shoal shoal)
	{
		double total = 0;
		for (Shoal.Roll roll : shoal.getRolls())
		{
			total += roll.chance();
		}
		return total;
	}

	@Test
	public void everyRareFishHasOneRegularShoal()
	{
		assertEquals(Shoal.MARLIN, Shoal.regularShoalOf(RareFish.SWIFT_MARLIN));
		assertEquals(Shoal.YELLOWFIN, Shoal.regularShoalOf(RareFish.ORANGEFIN));
		for (RareFish fish : RareFish.values())
		{
			assertFalse(Shoal.regularShoalOf(fish).isMixed());
		}
	}
}

package com.trawlingtracker;

import static com.trawlingtracker.RareFish.GIANT_BLUE_KRILL;
import static com.trawlingtracker.RareFish.GOLDEN_HADDOCK;
import static com.trawlingtracker.RareFish.HUGE_HALIBUT;
import static com.trawlingtracker.RareFish.ORANGEFIN;
import static com.trawlingtracker.RareFish.PURPLEFIN;
import static com.trawlingtracker.RareFish.SWIFT_MARLIN;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.util.QuantityFormatter;

/**
 * Shoal types and the rare fish each rolls for on every successful catch, by the player or a
 * crewmate, with the effective rates from the OSRS wiki.
 * <p>
 * A regular shoal has a 10% chance to turn into a mixed shoal for two stops. Mixed shoals roll
 * for several rare fish at once and yield the fish of several regular shoals.
 */
@Getter
enum Shoal
{
	GIANT_KRILL("Giant krill", ObjectID.SAILING_SHOAL_CLICKBOX_GIANT_KRILL, new String[]{"krill"},
		new Roll(GIANT_BLUE_KRILL, 1, 2_000)),
	HADDOCK("Haddock", ObjectID.SAILING_SHOAL_CLICKBOX_HADDOCK, new String[]{"haddock"},
		new Roll(GOLDEN_HADDOCK, 1, 2_000)),
	YELLOWFIN("Yellowfin", ObjectID.SAILING_SHOAL_CLICKBOX_YELLOWFIN, new String[]{"yellowfin", "orangefin"},
		new Roll(ORANGEFIN, 1, 4_000)),
	HALIBUT("Halibut", ObjectID.SAILING_SHOAL_CLICKBOX_HALIBUT, new String[]{"halibut"},
		new Roll(HUGE_HALIBUT, 1, 4_000)),
	BLUEFIN("Bluefin", ObjectID.SAILING_SHOAL_CLICKBOX_BLUEFIN, new String[]{"bluefin", "purplefin"},
		new Roll(PURPLEFIN, 1, 6_000)),
	MARLIN("Marlin", ObjectID.SAILING_SHOAL_CLICKBOX_MARLIN, new String[]{"marlin"},
		new Roll(SWIFT_MARLIN, 1, 6_000)),

	SHIMMERING("Shimmering", ObjectID.SAILING_SHOAL_CLICKBOX_SHIMMERING,
		new Shoal[]{GIANT_KRILL, HADDOCK, YELLOWFIN, HALIBUT},
		new Roll(GIANT_BLUE_KRILL, 9, 20_000),
		new Roll(GOLDEN_HADDOCK, 1, 2_500),
		new Roll(ORANGEFIN, 1, 10_000),
		new Roll(HUGE_HALIBUT, 1, 20_000)),
	GLISTENING("Glistening", ObjectID.SAILING_SHOAL_CLICKBOX_GLISTENING,
		new Shoal[]{YELLOWFIN, HALIBUT, BLUEFIN, MARLIN},
		new Roll(ORANGEFIN, 9, 40_000),
		new Roll(HUGE_HALIBUT, 1, 5_000),
		new Roll(PURPLEFIN, 1, 20_000),
		new Roll(SWIFT_MARLIN, 1, 40_000)),
	VIBRANT("Vibrant", ObjectID.SAILING_SHOAL_CLICKBOX_VIBRANT,
		new Shoal[]{BLUEFIN, MARLIN},
		new Roll(PURPLEFIN, 1, 6_000),
		new Roll(SWIFT_MARLIN, 1, 6_000));

	private final String displayName;

	/**
	 * The clickbox object the shoal shows up as in the scene.
	 */
	private final int objectId;

	/**
	 * Regular shoals: words in a catch message that name their fish, regular or rare.
	 */
	private final List<String> keywords;

	/**
	 * Mixed shoals: the regular shoals whose fish they yield.
	 */
	private final List<Shoal> mixes;

	private final List<Roll> rolls;

	Shoal(String displayName, int objectId, String[] keywords, Roll roll)
	{
		this(displayName, objectId, Arrays.asList(keywords), Collections.emptyList(), Collections.singletonList(roll));
	}

	Shoal(String displayName, int objectId, Shoal[] mixes, Roll... rolls)
	{
		this(displayName, objectId, Collections.emptyList(), Arrays.asList(mixes), Arrays.asList(rolls));
	}

	Shoal(String displayName, int objectId, List<String> keywords, List<Shoal> mixes, List<Roll> rolls)
	{
		this.displayName = displayName;
		this.objectId = objectId;
		this.keywords = keywords;
		this.mixes = mixes;
		this.rolls = rolls;
	}

	boolean isMixed()
	{
		return !mixes.isEmpty();
	}

	/**
	 * Whether the fish of the given regular shoal can be caught here.
	 */
	boolean yields(Shoal regular)
	{
		return this == regular || mixes.contains(regular);
	}

	Roll rollFor(RareFish fish)
	{
		for (Roll roll : rolls)
		{
			if (roll.getFish() == fish)
			{
				return roll;
			}
		}
		return null;
	}

	/**
	 * The one regular shoal that rolls for this fish.
	 */
	static Shoal regularShoalOf(RareFish fish)
	{
		for (Shoal shoal : values())
		{
			if (!shoal.isMixed() && shoal.rollFor(fish) != null)
			{
				return shoal;
			}
		}
		throw new IllegalArgumentException("No regular shoal rolls for " + fish);
	}

	static Shoal fromObjectId(int objectId)
	{
		for (Shoal shoal : values())
		{
			if (shoal.objectId == objectId)
			{
				return shoal;
			}
		}
		return null;
	}

	/**
	 * @param caught what a catch message says was caught, e.g. "3 marlin" or "a swift marlin"
	 * @return the regular shoal those fish belong to, or null if they aren't shoal fish
	 */
	static Shoal regularFromCatch(String caught)
	{
		String lower = caught.toLowerCase();
		for (Shoal shoal : values())
		{
			for (String keyword : shoal.keywords)
			{
				if (lower.contains(keyword))
				{
					return shoal;
				}
			}
		}
		return null;
	}

	@Value
	static class Roll
	{
		RareFish fish;
		int numerator;
		int denominator;

		double chance()
		{
			return (double) numerator / denominator;
		}

		/**
		 * e.g. "1/6,000" or "9/20,000".
		 */
		String rateText()
		{
			return numerator + "/" + QuantityFormatter.formatNumber(denominator);
		}
	}
}

package com.trawlingtracker;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import lombok.Getter;

/**
 * The Sailing XP drop sizes that count as one of the player's own trawling attempts.
 * <p>
 * Sizes are matched exactly rather than as a range, because sizes in between belong to crewmates.
 * With a cotton net a roll gives the player 15 XP at the right depth and 7.5 at the wrong one,
 * while a crewmate's roll gives about 10.5.
 * <p>
 * The game keeps experience to one decimal place and shows it rounded down, so an award of 7.5
 * arrives as 7 or 8 depending on the decimal already banked, while a whole 15 always arrives as 15.
 * Awards landing on the same tick are added together before that rounding.
 */
class CountedXpDrops
{
	/**
	 * A cotton net with no Keg of Horizon's Lure: 15 at the right depth, 7.5 at the wrong depth
	 * (landing as 7 or 8), and the player plus a crewmate on the same tick, which is 25.5 at the
	 * right depth and 18 at the wrong one.
	 */
	static final String DEFAULT = "7, 8, 15, 18, 25, 26";

	/**
	 * The same net with a Keg of Horizon's Lure aboard. Its 2.5% bonus is rounded down to one
	 * decimal, so the player's 15 becomes 15.3 and arrives as 15 or 16, the wrong depth's 7.5
	 * becomes 7.6 and arrives as 7 or 8, and a crewmate's 10.5 becomes 10.7, still arriving as
	 * 10 or 11. Together they make 15.3 + 10.7 = 26.0, which always arrives as 26, or 18.3 at the
	 * wrong depth, arriving as 18 or 19.
	 */
	static final String WITH_HORIZONS_LURE = "7, 8, 15, 16, 18, 19, 26";

	@Getter
	private final Set<Integer> sizes;

	private CountedXpDrops(Set<Integer> sizes)
	{
		this.sizes = Collections.unmodifiableSet(sizes);
	}

	/**
	 * Reads a comma separated list of sizes, ignoring anything that isn't a number.
	 *
	 * @return the sizes listed, or the default ones if the setting holds no usable number
	 */
	static CountedXpDrops parse(String setting)
	{
		Set<Integer> sizes = new LinkedHashSet<>();
		if (setting != null)
		{
			for (String part : setting.split("\\D+"))
			{
				if (part.isEmpty())
				{
					continue;
				}

				try
				{
					sizes.add(Integer.parseInt(part));
				}
				catch (NumberFormatException ignored)
				{
					// Too long to be an XP drop
				}
			}
		}
		return sizes.isEmpty() ? parse(DEFAULT) : new CountedXpDrops(sizes);
	}

	boolean counts(int drop)
	{
		return sizes.contains(drop);
	}
}

package com.trawlingtracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class TrawlingTrackerOverlay extends OverlayPanel
{
	private static final String TARGET = "Trawling tracker";

	/**
	 * Some net rolls every 2-5 ticks while trawling, so a longer gap means you've stopped.
	 */
	private static final Duration TRAWLING_TIMEOUT = Duration.ofSeconds(6);

	private static final Color HEADER_COLOR = Color.ORANGE;
	private static final Color MIXED_SHOAL_COLOR = Color.CYAN;

	/**
	 * Space kept between a line's left and right text.
	 */
	private static final int COLUMN_GAP = 10;

	private final TrawlingTrackerPlugin plugin;
	private final TrawlingTrackerConfig config;

	/**
	 * Measures this frame's lines, so the panel can be made wide enough for the longest.
	 */
	private FontMetrics metrics;
	private int widestLine;

	@Inject
	TrawlingTrackerOverlay(TrawlingTrackerPlugin plugin, TrawlingTrackerConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_LEFT);
		this.plugin = plugin;
		this.config = config;
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, TARGET);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset Soup", TARGET, e -> plugin.confirmResetSoup());
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset rare fish", TARGET, e -> plugin.chooseRareFishToReset());
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset angler's paint", TARGET, e -> plugin.confirmResetPaint());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		metrics = graphics.getFontMetrics();
		widestLine = 0;
		Instant now = Instant.now();
		TrawlAttemptCounter soup = plugin.getSoup();
		RareFishCounter rareFish = plugin.getRareFish();
		PaintCounter paint = plugin.getPaint();
		List<RareFish> shownFish = plugin.getShownFish();

		boolean showSoup = config.showSoup() && isRecent(soup.getLastAttempt(), now, TrawlAttemptCounter.TRIP_GAP);
		boolean showRareFish = !shownFish.isEmpty() && isRecent(rareFish.getLastCatch(), now, TrawlAttemptCounter.TRIP_GAP);
		boolean showPaint = config.showAnglersPaint() && rareFish.getCurrent() != null
			&& isRecent(paint.getLastCatch(), now, TrawlAttemptCounter.TRIP_GAP);
		if (!showSoup && !showRareFish && !showPaint)
		{
			return null;
		}

		boolean trawling = isRecent(plugin.getLastSailingXpDrop(), now, TRAWLING_TIMEOUT);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(trawling ? "Trawling" : "NOT trawling")
			.color(trawling ? Color.GREEN : Color.RED)
			.build());

		if (showSoup)
		{
			int oneIn = config.dropRate();
			long attempts = soup.getAttempts();
			addHeader("Soup", "1/" + QuantityFormatter.formatNumber(oneIn));
			addLine("Attempts:", QuantityFormatter.formatNumber(attempts));
			int perHour = soup.attemptsPerHour(now);
			if (perHour >= 0)
			{
				addLine("Attempts/hr:", QuantityFormatter.formatNumber(perHour));
			}
			addOdds(new DropOdds().add(attempts, 1.0 / oneIn));
		}

		if (showRareFish)
		{
			Shoal shoal = rareFish.getCurrent();
			if (shoal.isMixed())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(shoal.getDisplayName() + " shoal")
					.leftColor(MIXED_SHOAL_COLOR)
					.build());
			}

			for (RareFish fish : shownFish)
			{
				addHeader(fish.getDisplayName(), shoal.rollFor(fish).rateText());
				addLine("Catches:", QuantityFormatter.formatNumber(rareFish.getTotalCatches(fish)));
				addOdds(rareFish.getOdds(fish));
			}
		}

		if (showPaint)
		{
			addHeader("Angler's paint", "1/" + QuantityFormatter.formatNumber(PaintCounter.oneIn(rareFish.getCurrent())));
			addLine("Your catches:", QuantityFormatter.formatNumber(paint.getTotalCatches()));
			addOdds(paint.getOdds());
		}

		// Only used until the overlay is resized by hand, which then sets the width instead
		int width = widestLine + 2 * ComponentConstants.STANDARD_BORDER;
		panelComponent.setPreferredSize(new Dimension(Math.max(ComponentConstants.STANDARD_WIDTH, width), 0));
		return super.render(graphics);
	}

	private void measure(String left, String right)
	{
		widestLine = Math.max(widestLine, metrics.stringWidth(left) + COLUMN_GAP + metrics.stringWidth(right));
	}

	private void addHeader(String name, String rate)
	{
		measure(name, rate);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(name)
			.leftColor(HEADER_COLOR)
			.right(rate)
			.rightColor(HEADER_COLOR)
			.build());
	}

	private void addLine(String left, String right)
	{
		measure(left, right);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.build());
	}

	private void addOdds(DropOdds odds)
	{
		addLine("Drop rate:", String.format("%.3fx", odds.timesDropRate()));
		addLine("Chance by now:", String.format("%.2f%%", 100 * odds.chanceByNow()));
	}

	private static boolean isRecent(Instant time, Instant now, Duration within)
	{
		return time != null && Duration.between(time, now).compareTo(within) <= 0;
	}
}

package com.trawlingtracker;

import java.time.Duration;
import java.time.Instant;
import lombok.Getter;
import lombok.Setter;

/**
 * Tracks Sailing XP drops and counts the ones judged to be the player's trawling attempts.
 */
class TrawlAttemptCounter
{
	/**
	 * A gap this long between attempts starts a new trip for the per-hour rate.
	 */
	static final Duration TRIP_GAP = Duration.ofMinutes(5);

	private static final int NO_BASELINE = -1;

	private int lastXp = NO_BASELINE;

	/**
	 * All-time attempts on this account. Saved to config by the plugin.
	 */
	@Getter
	@Setter
	private long attempts;

	@Getter
	private Instant lastAttempt;

	private Instant tripStart;
	private int tripAttempts;

	/**
	 * Sets the XP total that the next update is compared against, without producing a drop.
	 */
	void setBaseline(int xp)
	{
		lastXp = xp;
	}

	/**
	 * Forgets the last XP total, so the next update only sets a new baseline. Use this when the
	 * client is about to resend stats (e.g. a new login), which must not count as a drop.
	 */
	void clearBaseline()
	{
		lastXp = NO_BASELINE;
	}

	/**
	 * @return how much XP this update added, or 0 if it was a baseline or no increase
	 */
	int onXp(int xp)
	{
		int previous = lastXp;
		lastXp = xp;
		if (previous == NO_BASELINE)
		{
			return 0;
		}
		return Math.max(0, xp - previous);
	}

	void recordAttempt(Instant now)
	{
		attempts++;
		if (lastAttempt == null || Duration.between(lastAttempt, now).compareTo(TRIP_GAP) > 0)
		{
			tripStart = now;
			tripAttempts = 0;
		}
		tripAttempts++;
		lastAttempt = now;
	}

	/**
	 * Zeroes everything except the baseline, so the next attempt still counts.
	 */
	void reset()
	{
		attempts = 0;
		lastAttempt = null;
		tripStart = null;
		tripAttempts = 0;
	}

	/**
	 * Attempts per hour this trip, or -1 until there are two attempts to measure between. The
	 * first attempt only starts the clock, so it isn't counted in the rate; this keeps the rate
	 * honest early in a trip and lets it decay while no attempts are coming in.
	 */
	int attemptsPerHour(Instant now)
	{
		if (tripAttempts < 2)
		{
			return -1;
		}

		long elapsedMs = Duration.between(tripStart, now).toMillis();
		if (elapsedMs <= 0)
		{
			return -1;
		}
		return (int) ((tripAttempts - 1) * 3_600_000L / elapsedMs);
	}
}

package com.trawlingtracker;

import com.google.inject.Provides;
